window.MG_LAZY_DATA["data/lazy/resources/c451-4d64754672b5da67.json"]={sha256:"4d64754672b5da677d120e3187537dd1db6ca2c5f405860bc408ae1e04b3f4f4",value:{"sources":[{"id":"v24-case-5567731fc8b02101","url":"https://www.trumpf.com/en_INT/solutions/applications/additive-manufacturing/laser-metal-deposition/","title":"TRUMPF Laser Metal Deposition","titleEn":"TRUMPF Laser Metal Deposition","publisher":"TRUMPF","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"c451","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"c451","related":[{"id":"c452","referenceUrls":["https://www.desktopmetal.com/resources/dfam-for-binder-jet"],"title":"金屬黏結劑噴印","titleEn":"Metal binder jetting","why":"用兩課的可觀察驗收條件比較模型邊界：三種質量不得混用，截面與基準可重建，且未把幾何恢復宣稱為服役認證。","whyEn":"Compare model boundaries using observable acceptance criteria: Feed, deposit and finished mass remain distinct, sections and datums are reproducible, and geometry is not claimed as service certification.","difference":"以三方向量測判斷單一縮放因子是否足夠，建立生胚到燒結件尺寸鏈。","differenceEn":"Determine whether one scale factor suffices from three-direction measurements and build a green-to-sintered dimension chain.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["近似矩形槽以 V=Lwh 計體積；捕獲率只連接送粉質量與沉積質量，不代表熔合品質。 教學槽長 40 mm、寬 6 mm、缺損深 1.2 mm，另留 0.3 mm 加工量；密度 8.0 g/cm³，捕獲率 0.60。 V=40×6×1.5=360 mm³=0.360 cm³；沉積質量 2.88 g，估計供粉 2.88/0.60=4.80 g。忽略側壁坡度與稀釋。","線性收縮 s 定義為 1−Lfinal/Lgreen，補償尺寸為 Ltarget/(1−s)，不是 Ltarget(1+s)。 教學目標孔距 25.00 mm，x 向收縮 16%，z 向 18%，先忽略非均勻變形。 x 生胚孔距=25/0.84=29.7619 mm；z=25/0.82=30.4878 mm。這是各向比例模型，不能預測局部翹曲。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["For a rectangular groove V=Lwh; capture efficiency connects supplied and deposited mass, not bond quality. Teaching groove: 40×6 mm, loss depth 1.2 mm, allowance 0.3 mm; density 8.0 g/cm³ and capture fraction 0.60. V=40×6×1.5=360 mm³=0.360 cm³; deposit mass 2.88 g and feed estimate 2.88/0.60=4.80 g. Side slopes and dilution are omitted.","Linear shrinkage s=1−Lfinal/Lgreen gives Lgreen=Ltarget/(1−s), not Ltarget(1+s). Teaching target spacing 25.00 mm; x shrinkage 16%, z shrinkage 18%; ignore nonuniform distortion initially. Green x spacing=25/0.84=29.7619 mm; z=25/0.82=30.4878 mm. Directional scaling does not predict local warpage.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"c461","referenceUrls":["https://www.schulergroup.com/major/us/technologien/produkte/grundlagen_blechumformung_tiefziehen_presse/index.html"],"title":"板材深引伸製程","titleEn":"Sheet-metal deep drawing","why":"用兩課的可觀察驗收條件比較模型邊界：三種質量不得混用，截面與基準可重建，且未把幾何恢復宣稱為服役認證。","whyEn":"Compare model boundaries using observable acceptance criteria: Feed, deposit and finished mass remain distinct, sections and datums are reproducible, and geometry is not claimed as service certification.","difference":"由杯底與側壁面積估胚料直徑，辨認忽略圓角與厚度變化的限制。","differenceEn":"Estimate blank diameter from cup-bottom and wall areas, retaining corner-radius and thickness limitations.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["近似矩形槽以 V=Lwh 計體積；捕獲率只連接送粉質量與沉積質量，不代表熔合品質。 教學槽長 40 mm、寬 6 mm、缺損深 1.2 mm，另留 0.3 mm 加工量；密度 8.0 g/cm³，捕獲率 0.60。 V=40×6×1.5=360 mm³=0.360 cm³；沉積質量 2.88 g，估計供粉 2.88/0.60=4.80 g。忽略側壁坡度與稀釋。","薄板厚度不變且忽略圓角時，πD²/4=πd²/4+πdh，因此 D=√(d²+4dh)。 教學杯直徑 d=60 mm，高 h=40 mm，板厚 1 mm；只作幾何估算。 D=√(60²+4×60×40)=114.891 mm；D/d=1.915，並不因此保證可單次引伸。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["For a rectangular groove V=Lwh; capture efficiency connects supplied and deposited mass, not bond quality. Teaching groove: 40×6 mm, loss depth 1.2 mm, allowance 0.3 mm; density 8.0 g/cm³ and capture fraction 0.60. V=40×6×1.5=360 mm³=0.360 cm³; deposit mass 2.88 g and feed estimate 2.88/0.60=4.80 g. Side slopes and dilution are omitted.","With constant thickness and negligible corners, πD²/4=πd²/4+π dh, so D=√(d²+4 dh). Teaching cup diameter d=60 mm, height h=40 mm, thickness 1 mm; geometry only. D=√(60²+4×60×40)=114.891 mm; D/d=1.915 does not prove one-draw feasibility.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v24-case-4dc9b5ab556e4615","url":"https://www.desktopmetal.com/resources/dfam-for-binder-jet","title":"Desktop Metal Binder Jet Design Principles","titleEn":"Desktop Metal Binder Jet Design Principles","publisher":"Desktop Metal","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v24-case-1e3bbe2df353208c","url":"https://www.schulergroup.com/major/us/technologien/produkte/grundlagen_blechumformung_tiefziehen_presse/index.html","title":"Deep Drawing with Presses","titleEn":"Deep Drawing with Presses","publisher":"Schuler","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
